        # Load libraries in the correct order
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define function signature for gsl_ran_flat
        self.gsl.gsl_ran_flat.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double)]
        self.gsl.gsl_ran_flat.restype = None

    def generate_random_number(self, rng, a, b):
        result = ctypes.c_double()
        self.gsl.gsl_ran_flat(rng, ctypes.c_double(a), ctypes.c_double(b), ctypes.byref(result))
        return float(result.value)

    def test(self):
        # Test case 1: basic functionality
        try:
            rng = ctypes.c_void_p(0x12345678)  # Example RNG pointer (should be valid in real use case)
