            print("Test 2 passed")
        except Exception as e:
            print(f"Test 2 failed: {e}")

        # Test case 3: zero bounds
        try:
            result = self.generate_random_number(rng, 0.0, 0.0)
            assert result == 0.0, "Result not zero"
            print("Test 3 passed")
        except Exception as e:
