import ctypes
import os

class gsl_combination(ctypes.Structure):
    _fields_ = []


def create_first_combination(n, k):
    if n < k or k < 0:
        return None

    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError:
        return None

    gsl.gsl_combination_alloc.argtypes = [ctypes.c_int]
    gsl.gsl_combination_alloc.restype = ctypes.POINTER(gsl_combination)
    gsl.gsl_combination_init_first.argtypes = [ctypes.POINTER(gsl_combination), ctypes.c_int]
    gsl.gsl_combination_free.argtypes = [ctypes.POINTER(gsl_combination)]

    comb = gsl.gsl_combination_alloc(k)
    if not comb:
        return None

    try:
        gsl.gsl_combination_init_first(comb, n)
    except:
        gsl.gsl_combination_free(comb)
        return None

    result = []
    for i in range(k):
        result.append(comb.contents.data[i])

    gsl.gsl_combination_free(comb)
    return result

