    ctypes.POINTER(gsl_matrix_complex),
    ctypes.POINTER(gsl_vector_complex)
]

def numpy_to_gsl_matrix_complex(np_array):
    rows, cols = np_array.shape
    mat = gsl_matrix_complex()
    mat.data = (ctypes.POINTER(gsl_complex) * (rows * cols))()
    for i in range(rows):
        for j in range(cols):
            mat.data[i * cols + j] = ctypes.pointer(gsl_complex(np_array[i, j].real, np_array[i, j].imag))
    return mat

def numpy_to_gsl_vector_complex(np_array):
    vec = gsl_vector_complex()
    vec.data = (gsl_complex * len(np_array))()
    for i in range(len(np_array)):
        vec.data[i] = gsl_complex(np_array[i].real, np_array[i].imag)
    return vec

