class gsl_eigen_gensymm_workspace(ctypes.Structure):
    _fields_ = []

ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

try:
    gsl.gsl_eigen_gensymm_workspace_alloc.argtypes = [ctypes.c_size_t, ctypes.c_size_t]
    gsl.gsl_eigen_gensymm_workspace_alloc.restype = ctypes.POINTER(gsl_eigen_gensymm_workspace)

    gsl.gsl_eigen_gensymm.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_vector), ctypes.POINTER(gsl_vector), ctypes.POINTER(gsl_eigen_gensymm_workspace)]
    gsl.gsl_eigen_gensymm.restype = ctypes.c_int

    gsl.gsl_eigen_gensymm_workspace_free.argtypes = [ctypes.POINTER(gsl_eigen_gensymm_workspace)]
    gsl.gsl_eigen_gensymm_workspace_free.restype = None

    def numpy_to_gsl_matrix(np_array):
        n = np_array.shape[0]
        mat = gsl_matrix()
        mat.contents = (ctypes.c_double * (n * n))()
        for i in range(n):
            for j in range(n):
                mat.contents[i * n + j] = np_array[i, j]
        return ctypes.pointer(mat)

    def numpy_to_gsl_vector(np_array):
        n = np_array.shape[0]
        vec = gsl_vector()
        vec.contents = (ctypes.c_double * n)()
        for i in range(n):
            vec.contents[i] = np_array[i]
        return ctypes.pointer(vec)

    def compute_gensymm_eigenvalues(A, B):
        n = A.shape[0]
        if B.shape[0] != n:
            raise ValueError("Matrices A and B must have the same dimensions.")

        gsl_matrix_A = numpy_to_gsl_matrix(A)
        gsl_matrix_B = numpy_to_gsl_matrix(B)
        gsl_vector_eigenvalues = numpy_to_gsl_vector(np.zeros(n))
        gsl_vector_work = numpy_to_gsl_vector(np.zeros(n))

        workspace = gsl.gsl_eigen_gensymm_workspace_alloc(n, n)

        status = gsl.gsl_eigen_gensymm(gsl_matrix_A, gsl_matrix_B, gsl_vector_eigenvalues, gsl_vector_work, workspace)

        if status != 0:
            raise RuntimeError(f"GSL eigenvalue computation failed with status code {status}")

        gsl.gsl_eigen_gensymm_workspace_free(workspace)

        eigenvalues = np.zeros(n)
        for i in range(n):
            eigenvalues[i] = gsl_vector_eigenvalues.contents[i]

        return eigenvalues

except Exception as e:
    raise RuntimeError(f"Failed to load GSL functions: {str(e)}")

