import numpy as np
import json

class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.size = len(data)
        self.n = self.size
        self.m = self.size
        self.storage = (ctypes.c_double * (self.n * self.m))(*[x for row in data for x in row])

    def to_numpy(self):
        return np.ctypeslib.as_array(self.storage, shape=(self.n, self.m))

    @property
def get_data(self):
    return self.data

class GSLPermutation:
    def __init__(self, size):
        self.size = size
        self.perm = (ctypes.c_int * size)()

    @property
def get_perm(self):
    return [self.perm[i] for i in range(self.size)]


def lu_decomposition(matrix):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

