    gsl.gsl_linalg_LU_decomp.restype = ctypes.c_int

    mat = GSLMatrix(matrix)
    size = mat.size
    perm = GSLPermutation(size)
    signum = ctypes.c_int(0)

    gsl.gsl_linalg_LU_decomp(mat.storage, ctypes.c_int(size), perm.perm, signum)

    lu_matrix = mat.to_numpy().tolist()
