class GSLMatrix:
    def __init__(self, rows, cols, data=None):
        self._matrix = gsl.gsl_matrix_alloc(rows, cols)
        if data is not None:
            for i in range(rows):
                for j in range(cols):
                    gsl.gsl_matrix_set(self._matrix, i, j, data[i][j])

    def __del__(self):
        if hasattr(self, '_matrix'):
            gsl.gsl_matrix_free(self._matrix)

    def scale(self, factor):
        gsl.gsl_matrix_scale(self._matrix, factor)

    def add(self, other):
        if self.shape != other.shape:
            raise ValueError("Matrix dimensions must match for addition")
        gsl.gsl_matrix_add(self._matrix, other._matrix)

    def sub(self, other):
        if self.shape != other.shape:
            raise ValueError("Matrix dimensions must match for subtraction")
        gsl.gsl_matrix_sub(self._matrix, other._matrix)

    def mul(self, other):
        if self.cols != other.rows:
            raise ValueError("Matrix dimensions must match for multiplication")
        result = GSLMatrix(self.rows, other.cols)
        gsl.gsl_matrix_mul(result._matrix, self._matrix)
        return result

    def transpose(self):
        result = GSLMatrix(self.cols, self.rows)
        gsl.gsl_matrix_transpose(result._matrix)
        return result

    def multiply_elements(self, other):
        if self.shape != other.shape:
            raise ValueError("Matrix dimensions must match for element-wise multiplication")
        gsl.gsl_matrix_mul_elements(self._matrix, other._matrix)

    def get(self, i, j):
        return gsl.gsl_matrix_get(self._matrix, i, j)

    def set(self, i, j, value):
        gsl.gsl_matrix_set(self._matrix, i, j, value)

    @property
    def rows(self):
        return ctypes.c_int(gsl.gsl_matrix_rows(self._matrix)).value

    @property
    def cols(self):
        return ctypes.c_int(gsl.gsl_matrix_cols(self._matrix)).value

    @property
    def shape(self):
        return (self.rows, self.cols)

    def to_array(self):
        data = np.zeros((self.rows, self.cols), dtype=np.float64)
        for i in range(self.rows):
            for j in range(self.cols):
                data[i, j] = self.get(i, j)
        return data

    def __str__(self):
        return str(self.to_array())

    def __repr__(self):
        return f"GSLMatrix({self.shape})"

    def perform_operation(self, func, scalar=1.0):
        for i in range(self.rows):
            for j in range(self.cols):
                self.set(i, j, func(self.get(i, j), scalar))

    def perform_operation_on_vector(self, func, vector):
        if len(vector) != self.rows * self.cols:
            raise ValueError("Vector length must match the number of elements in the matrix")
        for i in range(self.rows):
            for j in range(self.cols):
                self.set(i, j, func(self.get(i, j), vector[i * self.cols + j]))

