class GSLMatrix:
    def __init__(self, self, rows, cols):
        self.rows = rows
        self.cols = cols
        self._allocate()

    def _allocate(self):
        self.data = ctypes.POINTER(ctypes.POINTER(ctypes.c_double))()
        self.data = ctypes.c_void_p(ctypes.addressof(ctypes.c_double * (self.rows * self.cols)()))

    def free(self):
        pass

