        gsl.gsl_filter_impulse.restype = ctypes.c_int
        gsl.gsl_filter_impulse.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_double]
        result = gsl.gsl_filter_impulse(self.workspace, ctypes.c_double(signal), ctypes.c_double(threshold), self.size, ctypes.c_double(threshold))
        return result


