        self.size = size
        self.buf = (ctypes.c_double * size)()
        self.head = 0
        self.tail = 0
        self.full = False

    def insert_into_ringbuf(self, values):
        for val in values:
            if self.full:
                self.head = (self.head + 1) % self.size
            self.buf[self.tail] = val
            self.tail = (self.tail + 1) % self.size
            self.full = (self.tail == self.head)

    def copy_ringbuf_to_list(self):
        result = []
        if self.full:
            for i in range(self.size):
                result.append(self.buf[i])
        else:
            for i in range(self.head, self.tail):
                result.append(self.buf[i])
        return result

