class gsl_function(ctypes.Structure):
    _fields_ = [('f', ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)),
                ('params', ctypes.c_void_p)]

def func_wrapper(x, params):
    py_func = ctypes.cast(params, ctypes.POINTER(ctypes.c_void_p)).contents.value
    return py_func(x)

def compute_integral(py_func, a, b, epsabs, epsrel, n):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl.gsl_integration_romberg_alloc.argtypes = [ctypes.c_int]
    gsl.gsl_integration_romberg_alloc.restype = ctypes.c_void_p

    gsl.gsl_integration_romberg.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_int, ctypes.c_void_p]
    gsl.gsl_integration_romberg.restype = ctypes.c_int

    gsl.gsl_integration_romberg_free.argtypes = [ctypes.c_void_p]
    gsl.gsl_integration_romberg_free.restype = None

    workspace = gsl.gsl_integration_romberg_alloc(n)

    func = gsl_function()
    func.f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(func_wrapper)
    func.params = ctypes.cast(ctypes.pointer(ctypes.c_void_p(py_func)), ctypes.c_void_p)

    result = ctypes.c_double(0)
    error = ctypes.c_double(0)
    neval = ctypes.c_int(0)

    status = gsl.gsl_integration_romberg(workspace, a, b, epsabs, epsrel, n, ctypes.byref(result), ctypes.byref(error), ctypes.byref(neval))

    if status != 0:
        raise Exception(f"Integration failed with status code {status}")

    gsl.gsl_integration_romberg_free(workspace)
    return float(result), int(neval.value)

