import ctypes
import os

def allocate_normal_state(p):
    if not isinstance(p, int) or p <= 0:
        return None

    lib_path = os.path.abspath("/usr/local/gsl/lib/libgsl.so")
    try:
        gsl = ctypes.CDLL(lib_path, mode=ctypes.RTLD_GLOBAL)
    except OSError:
        return None

    gsl.gsl_ran_normal_alloc.argtypes = [ctypes.c_int]
    gsl.gsl_ran_normal_alloc.restype = ctypes.c_void_p

    result = gsl.gsl_ran_normal_alloc(p)
    if not result:
        return None

    return result

